 policyrows.append({'POLICY_ID':b.policy_id,'VERSION':b.version,'SOURCE_IDENTITY':codec._wire(b.artifact.identity),'SOURCE_PIN':codec._wire(b.artifact),'SOURCE_BYTE_HASH':sha(raw),'SEMANTIC_CONTRACT_HASH':semantic,'IMPLEMENTATION_RULE_VERSION':b.implementation_rule_version,'APPLICABILITY':'A14_EXTERNAL_STATE_SUPPORTED' if b.version in ['E1-SELECTION-1-P05','E1-SELECTION-1-P06'] else 'WRONG_VERSION_FOR_EXTERNAL_DECISION_STATE','SCOPE':'Replay schema version of admitted selector; not a native permission or execution scope','LINEAGE':'Applies to exact supplied bundle lineage; does not rewrite it','CURRENTNESS':'PASS_UNCHANGED_REVIEWED_REGISTRY_AND_RAW_POLICY_BYTES','SELECTED':False})
